package com.suks.sittiporn.lslamic.forgetpassword;import androidx.appcompat.app.AppCompatActivity;import android.os.Bundle;import com.suks.sittiporn.lslamic.R;public class ForgetPasswordActivity extends AppCompatActivity {    @Override    protected void onCreate(Bundle savedInstanceState) {        super.onCreate(savedInstanceState);        setContentView(R.layout.forget_password_activity);        if (savedInstanceState == null) {            getSupportFragmentManager().beginTransaction()                    .replace(R.id.container, ForgetPasswordFragment.newInstance())                    .commitNow();        }    }}